export function provincesFor(countryCode: string): Province[] {
  return PROVINCES_BY_COUNTRY[countryCode?.toUpperCase()] ?? [];
}

/** All cities in a country, or only those inside a province when given. */
export function citiesFor(countryCode: string, province?: string): City[] {
  const provinces = provincesFor(countryCode);
  const scoped = province ? provinces.filter((p) => p.en === province) : provinces;
  const seen = new Map<string, City>();
  for (const p of scoped) for (const city of p.cities) if (!seen.has(city.en)) seen.set(city.en, city);
  return [...seen.values()].sort((a, b) => a.en.localeCompare(b.en));
}

/** Province that contains a given city (first match). */
export function provinceOfCity(countryCode: string, city: string): string {
  return provincesFor(countryCode).find((p) => p.cities.some((c) => c.en === city))?.en ?? "";
}
